CREATE OR REPLACE PROCEDURE sp(para_Driver_ID integer, para_Name text, para_Age integer, para_School_ID integer, para_If_full_time text) LANGUAGE plpgsql AS
$$
BEGIN
    IF para_Driver_ID < para_Age THEN
        UPDATE "driver" SET "Name" = 'A';
        DELETE FROM "driver" WHERE "Driver_ID" = 1;
        UPDATE "driver" SET "Name" = 'B';
        DELETE FROM "driver" WHERE "Driver_ID" = 2;
        UPDATE "driver" SET "Name" = 'C';
        DELETE FROM "driver" WHERE "Driver_ID" = 3;
        UPDATE "school_bus" SET "If_full_time" = 'log_A';
        DELETE FROM "school_bus" WHERE "School_ID" = 1;
        UPDATE "school_bus" SET "If_full_time" = 'log_B';
        DELETE FROM "school_bus" WHERE "School_ID" = 2;
        UPDATE "school_bus" SET "If_full_time" = 'log_C';
        DELETE FROM "school_bus" WHERE "School_ID" = 3;
        UPDATE "driver" SET "Name" = para_Name;
        DELETE FROM "driver" WHERE "Driver_ID" = para_Driver_ID;
        UPDATE "school_bus" SET "If_full_time" = para_If_full_time;
        DELETE FROM "school_bus" WHERE "School_ID" = para_School_ID;
    END IF;
END;
$$;

